package coordinator

import (
	"fmt"
	"net/http"
)

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>parallaxd control room</title><style>
:root{color-scheme:dark;--bg:#080b10;--panel:#111722;--panel2:#171e2b;--line:#273244;--text:#edf3ff;--muted:#94a3b8;--blue:#67a8ff;--green:#35d07f;--red:#ff6868;--amber:#f7bd55;--shadow:0 18px 50px #0007}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#15223b 0,transparent 28rem),var(--bg);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui}button,input,select,textarea{font:inherit}button{cursor:pointer}.shell{max-width:1440px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:13px}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(145deg,#79b5ff,#6b5cff);box-shadow:0 0 35px #637bff66;display:grid;place-items:center;font-weight:900}.brand h1{font-size:18px;margin:0}.brand p,.muted{color:var(--muted);margin:2px 0}.auth{display:flex;gap:8px;align-items:center}.control,.btn{border:1px solid var(--line);background:#101722;color:var(--text);border-radius:9px;padding:9px 11px}.btn:hover{border-color:var(--blue)}.btn.primary{background:#2b68bd;border-color:#478de9}.btn.danger{color:#ff9999}.nav{display:flex;gap:5px;margin:24px 0 18px;border-bottom:1px solid var(--line)}.nav button{border:0;background:none;color:var(--muted);padding:11px 14px;border-bottom:2px solid transparent}.nav button.active{color:var(--text);border-color:var(--blue)}.view{display:none}.view.active{display:block}.hero{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:15px 0 20px}.hero h2{font-size:30px;margin:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:12px}.card{background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:13px;padding:16px;box-shadow:0 8px 25px #0002}.card h3{margin:0 0 5px;font-size:15px}.card .value{font-size:26px;font-weight:760}.badge{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:99px;padding:3px 8px;color:var(--muted);font-size:12px}.badge:before{content:'';width:7px;height:7px;border-radius:50%;background:var(--muted)}.badge.up:before{background:var(--green)}.badge.down:before{background:var(--red)}.badge.unknown:before{background:var(--amber)}.section{margin:25px 0}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 10px}.section-head h2{margin:0;font-size:18px}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:13px;background:var(--panel)}table{border-collapse:collapse;width:100%;min-width:850px}th,td{text-align:left;padding:11px 13px;border-bottom:1px solid var(--line);vertical-align:middle}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em;background:#0e141e}tr:last-child td{border:0}tr:hover td{background:#151d29}.name{font-weight:650}.target{color:#b8c6da;font-family:ui-monospace,monospace;font-size:12px}.actions{display:flex;gap:6px}.actions .btn{padding:5px 8px;font-size:12px}.empty{text-align:center;color:var(--muted);padding:30px}.notice{position:fixed;right:24px;bottom:24px;max-width:430px;background:#172236;border:1px solid #385179;border-radius:11px;padding:12px 15px;box-shadow:var(--shadow);display:none;z-index:20}.notice.error{border-color:#8c4242}.modal{position:fixed;inset:0;background:#02050acc;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.modal.open{display:flex}.dialog{width:min(850px,100%);max-height:92vh;overflow:auto;background:#0f1621;border:1px solid #334159;border-radius:16px;box-shadow:var(--shadow);padding:20px}.dialog-head{display:flex;justify-content:space-between;align-items:center}.dialog h2{margin:0}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.field{display:grid;gap:5px}.field label{color:var(--muted);font-size:12px}.field input,.field select,.field textarea{width:100%;border:1px solid var(--line);background:#0a1019;color:var(--text);border-radius:8px;padding:9px}.field textarea{min-height:76px;resize:vertical}.span2{grid-column:span 2}.span3{grid-column:span 3}.checkline{display:flex;align-items:center;gap:8px;margin-top:25px}.dialog-foot{display:flex;justify-content:space-between;gap:10px;margin-top:18px}.test-results{margin-top:12px}.revision{display:flex;justify-content:space-between;gap:15px;align-items:center}.status-row{display:flex;justify-content:space-between;gap:10px}.status-row+.status-row{margin-top:8px}.incident-actions{margin-top:10px}.hidden{display:none!important}@media(max-width:760px){.shell{padding:15px}.top,.hero{align-items:flex-start;flex-direction:column}.auth{width:100%;flex-wrap:wrap}.form-grid{grid-template-columns:1fr}.span2,.span3{grid-column:auto}}
</style></head><body><div class="shell">
<header class="top"><div class="brand"><div class="mark">P</div><div><h1>parallaxd</h1><p id="meta">Connecting to the fleet…</p></div></div><div class="auth"><input id="actor" class="control" placeholder="Operator"><input id="token" class="control" type="password" placeholder="API token"><button id="saveAuth" class="btn">Use credentials</button></div></header>
<nav class="nav"><button data-view="overview" class="active">Overview</button><button data-view="monitors">Monitors</button><button data-view="incidents">Incidents & silences</button><button data-view="audit">Audit</button></nav>
<main>
<section id="overview" class="view active"><div class="hero"><div><p class="muted">Fleet health</p><h2>Control room</h2></div><span id="haBadge" class="badge unknown">loading</span></div><div id="summary" class="grid"></div><div class="section"><div class="section-head"><h2>Components</h2></div><div id="components" class="grid"></div></div><div class="section"><div class="section-head"><h2>Checks</h2></div><div id="checks" class="grid"></div></div><div class="section"><div class="section-head"><h2>History</h2></div><div id="history" class="grid"></div></div></section>
<section id="monitors" class="view"><div class="hero"><div><p class="muted">Live replicated catalogue</p><h2>Monitors</h2></div><button id="newMonitor" class="btn primary">+ New monitor</button></div><div class="toolbar"><input id="monitorSearch" class="control" placeholder="Search name or target"><select id="monitorFilter" class="control"><option value="all">All monitors</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option></select></div><div class="table-wrap section"><table><thead><tr><th>Status</th><th>Name / target</th><th>Type</th><th>Schedule</th><th>Owner</th><th>Quorum</th><th>Actions</th></tr></thead><tbody id="monitorRows"></tbody></table></div></section>
<section id="incidents" class="view"><div class="hero"><div><p class="muted">Human workflow</p><h2>Active incidents</h2></div></div><div id="incidentCards" class="grid"></div><div class="section"><div class="section-head"><h2>Create silence</h2></div><form id="silenceForm" class="card form-grid"><div class="field"><label>Name</label><input id="silenceName" required></div><div class="field"><label>Ends</label><input id="silenceEnd" type="datetime-local" required></div><div class="field"><label>Scope</label><select id="scopeType"><option value="checks">Checks</option><option value="components">Components</option><option value="probers">Probers</option><option value="fleet">Entire fleet</option></select></div><div class="field span2"><label>Names, comma separated</label><input id="scopeNames"></div><div class="field"><label>Comment</label><input id="silenceComment"></div><button class="btn primary" type="submit">Create silence</button></form></div><div class="section"><div class="section-head"><h2>Current silences</h2></div><div id="silenceCards" class="grid"></div></div></section>
<section id="audit" class="view"><div class="hero"><div><p class="muted">Durable catalogue history</p><h2>Monitor revisions</h2></div></div><div id="revisionCards" class="grid"></div><div class="section"><div class="section-head"><h2>Diagnostics</h2></div><div id="diagnostics" class="grid"></div></div></section>
</main></div><p id="notice" class="notice"></p>
<div id="monitorModal" class="modal"><form id="monitorForm" class="dialog"><div class="dialog-head"><div><p class="muted">Validated before activation</p><h2 id="modalTitle">New monitor</h2></div><button type="button" id="closeModal" class="btn">Close</button></div><div class="form-grid">
<div class="field"><label>Name</label><input id="mName" required pattern="[A-Za-z0-9._-]+"></div><div class="field"><label>Kind</label><select id="mKind"><option>http</option><option>tcp</option><option>banner</option><option>dns</option><option>tls</option><option>smtp</option><option>icmp</option></select></div><div class="field"><label>Vantage</label><select id="mVantage"><option>public</option><option>internal</option></select></div>
<div class="field span2"><label>Target</label><input id="mTarget" required placeholder="https://example.com/health"></div><div class="field"><label>Preferred prober</label><select id="mProber"></select></div><div class="field"><label>Interval</label><input id="mInterval" value="1m" required></div><div class="field"><label>Timeout</label><input id="mTimeout" value="10s" required></div><div class="field checkline"><input id="mEnabled" type="checkbox" checked><label for="mEnabled">Enabled</label></div>
<div class="field"><label>Agree</label><input id="mAgree" type="number" min="1" value="2"></div><div class="field"><label>Ask (of)</label><input id="mOf" type="number" min="1" value="3"></div><div class="field checkline"><input id="mProviders" type="checkbox" checked><label for="mProviders">Distinct providers</label></div>
<div class="field span2 protocol"><label>Expected body/banner text</label><input id="mExpectBody"></div><div class="field protocol"><label>HTTP method</label><input id="mMethod" placeholder="GET"></div><div class="field span2 protocol"><label>HTTP headers (JSON)</label><textarea id="mHeaders" placeholder='{"Authorization":"Bearer …"}'></textarea></div><div class="field protocol"><label>Expected status codes</label><input id="mStatuses" placeholder="200, 204"></div><div class="field span2 protocol"><label>Request body / banner send</label><textarea id="mBody"></textarea></div><div class="field protocol"><label>DNS record</label><select id="mDNS"><option value="">Default A</option><option>A</option><option>AAAA</option><option>MX</option><option>TXT</option></select></div><div class="field protocol"><label>TLS server name</label><input id="mServerName"></div><div class="field checkline protocol"><input id="mStartTLS" type="checkbox"><label for="mStartTLS">STARTTLS</label></div>
</div><div id="testResults" class="test-results"></div><div class="dialog-foot"><button type="button" id="testMonitor" class="btn">Test from all probers</button><div><button type="button" id="validateMonitor" class="btn">Validate</button> <button type="submit" class="btn primary">Save monitor</button></div></div></form></div>
<script>
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={monitors:[],peers:[],editing:null,incidents:[],silences:[]};
actor.value=sessionStorage.getItem('parallaxd.actor')||'';token.value=sessionStorage.getItem('parallaxd.token')||'';saveAuth.onclick=()=>{sessionStorage.setItem('parallaxd.actor',actor.value.trim());sessionStorage.setItem('parallaxd.token',token.value);note('Credentials saved for this tab');load()};
function note(s,bad=false){notice.textContent=s;notice.className='notice'+(bad?' error':'');notice.style.display='block';setTimeout(()=>notice.style.display='none',6000)}
async function json(url){const r=await fetch(url);if(!r.ok)throw new Error(url+' returned '+r.status);return r.json()}
async function operatorJSON(url){const secret=token.value;if(!secret)throw new Error('Enter the operator token to manage monitors');const r=await fetch(url,{headers:{Authorization:'Bearer '+secret}});if(!r.ok)throw new Error((await r.text()).trim()||('request returned '+r.status));return r.json()}
async function mutate(url,method,body={}){const who=actor.value.trim(),secret=token.value;if(!who||!secret)throw new Error('Enter operator name and API token first');body.actor=who;const r=await fetch(url,{method,headers:{Authorization:'Bearer '+secret,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error((await r.text()).trim()||('request returned '+r.status));return r.status===204?null:r.json()}
function card(title,status,detail,value=''){return '<article class="card"><div class="status-row"><h3>'+esc(title)+'</h3><span class="badge '+esc(status)+'">'+esc(status)+'</span></div>'+(value?'<div class="value">'+esc(value)+'</div>':'')+'<p class="muted">'+esc(detail)+'</p></article>'}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.view).classList.add('active')});
function renderOverview(e,d,h){const ha=d.ha||{},n=d.notifications||{},q=d.result_queue||{};haBadge.className='badge '+(ha.last_replication_error?'down':ha.active?'up':'unknown');haBadge.textContent=(ha.role||'primary')+(ha.active?' · active':' · following');summary.innerHTML=card('Checks','up','configured and assigned',e.checks.length)+card('Probers',e.probers?'up':'down','registered vantage points',e.probers)+card('Notifications',n.pending?'unknown':'up',(n.pending||0)+' pending · '+(n.failures||0)+' failures')+card('Replication',ha.last_replication_error?'down':'up',ha.last_replication_error||((ha.replication_lag_ms||0)+'ms apply lag'));components.innerHTML=(e.components||[]).map(x=>card(x.component,x.status,x.description||x.checks.join(', '))).join('')||'<p class="empty">No components.</p>';checks.innerHTML=(e.checks||[]).map(x=>card(x.check,x.status,x.target+(x.assigned_to?' · '+x.assigned_to:''))).join('');history.innerHTML=(h||[]).map(x=>card(x.check,x.down?'unknown':'up',(x.samples||0)+' samples · '+(((x.up||0)+(x.down||0))?(100*x.availability).toFixed(3)+'% availability':'undecided')+(x.p95_latency_ms?' · p95 '+x.p95_latency_ms+'ms':''))).join('')}
function monitorSpec(){let headers={};if(mHeaders.value.trim())headers=JSON.parse(mHeaders.value);const statuses=mStatuses.value.split(',').map(x=>Number(x.trim())).filter(Number.isFinite);return{name:mName.value.trim(),enabled:mEnabled.checked,kind:mKind.value,target:mTarget.value.trim(),vantage:mVantage.value,interval:mInterval.value.trim(),timeout:mTimeout.value.trim(),quorum:{agree:Number(mAgree.value),of:Number(mOf.value),distinct_providers:mProviders.checked},prober:mProber.value,expect_status:statuses,expect_body:mExpectBody.value,http_method:mMethod.value.trim(),http_headers:headers,http_body:mKind.value==='http'?mBody.value:'',send:mKind.value==='banner'?mBody.value:'',dns_record:mDNS.value,server_name:mServerName.value.trim(),start_tls:mStartTLS.checked}}
function fillForm(m={}){state.editing=m.name||null;modalTitle.textContent=m.name?'Edit monitor':'New monitor';mName.value=m.name||'';mName.disabled=!!m.name;mEnabled.checked=m.enabled!==false;mKind.value=m.kind||'http';mTarget.value=m.target||'';mVantage.value=m.vantage||'public';mInterval.value=m.interval||'1m';mTimeout.value=m.timeout||'10s';mAgree.value=m.quorum?.agree||2;mOf.value=m.quorum?.of||3;mProviders.checked=m.quorum?.distinct_providers!==false;mProber.innerHTML='<option value="">Automatic assignment</option>'+state.peers.map(x=>'<option>'+esc(x.name)+'</option>').join('');mProber.value=m.prober||'';mExpectBody.value=m.expect_body||'';mMethod.value=m.http_method||'';mHeaders.value=m.http_headers?JSON.stringify(m.http_headers,null,2):'';mStatuses.value=(m.expect_status||[]).join(', ');mBody.value=m.http_body||m.send||'';mDNS.value=m.dns_record||'';mServerName.value=m.server_name||'';mStartTLS.checked=!!m.start_tls;testResults.innerHTML='';monitorModal.classList.add('open')}
newMonitor.onclick=()=>fillForm();closeModal.onclick=()=>monitorModal.classList.remove('open');monitorModal.onclick=e=>{if(e.target===monitorModal)monitorModal.classList.remove('open')};
function renderMonitors(){const q=monitorSearch.value.toLowerCase(),filter=monitorFilter.value;const items=state.monitors.filter(m=>(!q||(m.name+' '+m.target).toLowerCase().includes(q))&&(filter==='all'||(filter==='enabled')===m.enabled));monitorRows.innerHTML=items.map(m=>'<tr><td><span class="badge '+(m.enabled?'up':'unknown')+'">'+(m.enabled?'enabled':'disabled')+'</span></td><td><div class="name">'+esc(m.name)+'</div><div class="target">'+esc(m.target)+'</div></td><td>'+esc(m.kind)+' · '+esc(m.vantage)+'</td><td>'+esc(m.interval)+' / '+esc(m.timeout)+'</td><td>'+esc(m.prober||'automatic')+'</td><td>'+m.quorum.agree+' of '+m.quorum.of+(m.quorum.distinct_providers?' · providers':'')+'</td><td><div class="actions"><button class="btn" data-action="edit" data-monitor="'+esc(m.name)+'">Edit</button><button class="btn" data-action="clone" data-monitor="'+esc(m.name)+'">Clone</button><button class="btn danger" data-action="delete" data-monitor="'+esc(m.name)+'">Delete</button></div></td></tr>').join('')||'<tr><td colspan="7" class="empty">No matching monitors.</td></tr>'}
monitorSearch.oninput=renderMonitors;monitorFilter.onchange=renderMonitors;monitorRows.onclick=async e=>{const button=e.target.closest('button[data-action]');if(!button)return;const n=button.dataset.monitor,m=state.monitors.find(x=>x.name===n);if(button.dataset.action==='edit')fillForm(m);if(button.dataset.action==='clone'){const copy=structuredClone(m);copy.name+='-copy';fillForm(copy);state.editing=null;mName.disabled=false;modalTitle.textContent='Clone monitor'}if(button.dataset.action==='delete'){if(!confirm('Delete '+n+'? History remains, but probing stops immediately.'))return;try{await mutate('/v1/monitors/'+encodeURIComponent(n),'DELETE',{});note('Monitor deleted');await load()}catch(err){note(err.message,true)}}};
validateMonitor.onclick=async()=>{try{await mutate('/v1/monitors/validate','POST',{monitor:monitorSpec()});note('Monitor is valid')}catch(e){note(e.message,true)}};testMonitor.onclick=async()=>{try{testResults.innerHTML='<p class="muted">Testing…</p>';const out=await mutate('/v1/monitors/test','POST',{monitor:monitorSpec()});testResults.innerHTML=out.map(x=>card(x.prober,x.error?'unknown':x.result.status,x.error||x.result.detail||((x.result.latency||0)/1e6).toFixed(1)+'ms')).join('')}catch(e){testResults.innerHTML='';note(e.message,true)}};
monitorForm.onsubmit=async e=>{e.preventDefault();try{const monitor=monitorSpec(),editing=state.editing;await mutate(editing?'/v1/monitors/'+encodeURIComponent(editing):'/v1/monitors',editing?'PUT':'POST',{monitor});monitorModal.classList.remove('open');note(editing?'Monitor updated':'Monitor created');await load()}catch(e){note(e.message,true)}};
function renderIncidents(){const live=state.incidents.filter(x=>x.active);incidentCards.innerHTML=live.map(x=>card(x.subject,'down',x.kind+' since '+new Date(x.opened_at).toLocaleString()+(x.acknowledged_by?' · acknowledged by '+x.acknowledged_by:'')) .replace('</article>','<div class="incident-actions actions"><button class="btn" onclick="incidentAction('+x.id+',\'acknowledge\')">Acknowledge</button><button class="btn danger" onclick="incidentAction('+x.id+',\'resolve\')">Resolve</button></div></article>')).join('')||'<p class="empty">No active incidents.</p>';const now=Date.now(),silences=state.silences.filter(x=>!x.cancelled_at&&new Date(x.ends_at)>now);silenceCards.innerHTML=silences.map(x=>card(x.name,'unknown','until '+new Date(x.ends_at).toLocaleString()+' · '+([...(x.checks||[]),...(x.components||[]),...(x.probers||[])].join(', ')||'entire fleet')).replace('</article>','<div class="actions"><button class="btn danger" onclick="cancelSilence('+x.id+')">Cancel</button></div></article>')).join('')||'<p class="empty">No active silences.</p>'}
window.incidentAction=async(id,action)=>{try{await mutate('/v1/incidents/'+id+'/'+action,'POST',{note:prompt('Note')||''});await load()}catch(e){note(e.message,true)}};window.cancelSilence=async id=>{try{await mutate('/v1/silences/'+id,'DELETE',{note:prompt('Cancellation note')||''});await load()}catch(e){note(e.message,true)}};silenceForm.onsubmit=async e=>{e.preventDefault();try{const type=scopeType.value,names=scopeNames.value.split(',').map(x=>x.trim()).filter(Boolean),body={name:silenceName.value.trim(),ends_at:new Date(silenceEnd.value).toISOString(),comment:silenceComment.value.trim()};if(type!=='fleet')body[type]=names;await mutate('/v1/silences','POST',body);silenceForm.reset();await load()}catch(e){note(e.message,true)}};
function renderAudit(revisions,d){revisionCards.innerHTML=[...revisions].reverse().map(r=>'<article class="card"><div class="revision"><div><h3>#'+r.id+' · '+esc(r.action)+' '+esc(r.subject||'')+'</h3><p class="muted">'+new Date(r.at).toLocaleString()+' · '+esc(r.actor)+' · '+r.catalog.length+' monitors</p></div><button class="btn" onclick="rollback('+r.id+')">Rollback</button></div></article>').join('')||'<p class="empty">No runtime catalogue changes yet.</p>';const ha=d.ha||{},n=d.notifications||{},h=d.history||{};diagnostics.innerHTML=card('HA',ha.last_replication_error?'down':ha.active?'up':'unknown',ha.last_replication_error||((ha.role||'primary')+' · '+(ha.replication_lag_ms||0)+'ms lag'))+card('History',h.last_error?'down':'up',(h.retained||0)+' retained · '+(h.write_failures||0)+' failures')+card('Notifications',n.last_error?'down':'up',(n.pending||0)+' pending · '+(n.attempts||0)+' attempts')}
window.rollback=async id=>{if(!confirm('Replace the live catalogue with revision #'+id+'?'))return;try{await mutate('/v1/monitors/revisions/'+id+'/rollback','POST',{});note('Catalogue rolled back');await load()}catch(e){note(e.message,true)}};
async function load(){try{const [e,d,h,p,i,s]=await Promise.all([json('/v1/export'),json('/v1/diagnostics'),json('/v1/history/summary'),json('/v1/monitor-options'),json('/v1/incidents'),json('/v1/silences')]);state={...state,peers:p,incidents:i,silences:s};meta.textContent=e.coordinator+' · '+e.probers+' probers · updated '+new Date(e.generated_at).toLocaleTimeString();renderOverview(e,d,h);renderIncidents();if(token.value){try{const [m,r]=await Promise.all([operatorJSON('/v1/monitors'),operatorJSON('/v1/monitors/revisions')]);state.monitors=m;renderMonitors();renderAudit(r,d)}catch(err){renderAudit([],d);monitorRows.innerHTML='<tr><td colspan="7" class="empty">'+esc(err.message)+'</td></tr>';revisionCards.innerHTML='<p class="empty">'+esc(err.message)+'</p>';note(err.message,true)}}else{renderAudit([],d);monitorRows.innerHTML='<tr><td colspan="7" class="empty">Enter operator credentials to manage monitors.</td></tr>';revisionCards.innerHTML='<p class="empty">Enter operator credentials to view catalogue history.</p>'}}catch(e){note(e.message,true);meta.textContent='Unable to load fleet'} }
load();setInterval(load,30000);
</script></body></html>`

func (c *Coordinator) handleDashboard(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Security-Policy", "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Frame-Options", "DENY")
	fmt.Fprint(w, dashboardHTML)
}
